 const balance=id=>Number(banks.rows.find(b=>b.id===id)?.opening_balance||0)+bankTx.rows.filter(x=>x.bank_account_id===id).reduce((sum,x)=>sum+(String(x.direction||"").toUpperCase()==="WITHDRAWAL"||String(x.direction||"").toUpperCase()==="DEBIT"?-1:1)*Number(x.amount||0),0);
 const topRows=useMemo(()=>{const r=config.topAgents||{};const startDate=r.start||monthStart,endDate=r.end||monthEnd,basis=r.dateBasis||"FINALIZED";const completed=transactions.rows.filter(t=>{const statuses=[t.status,t.transaction_status].map(value=>String(value||"").toUpperCase().replace(/[^A-Z]/g,""));const date=String(basis==="FINALIZED"?(t.finalized_date||t.finalized_at||t.closed_at||""):(t.close_date||"")).slice(0,10);return statuses.some(status=>["CLOSED","COMPLETED","FINALIZED","CLOSEDWON","PAID"].includes(status))&&!!date&&date>=startDate&&date<=endDate});const totals=new Map(agents.rows.map(agent=>[String(agent.id),{id:String(agent.id),name:agentName(agent),units:0,volume:0,gci:0,listings:0,leaseListings:0,saleListings:0}]));completed.forEach(t=>{const agent=agents.rows.find(a=>String(a.id)===String(t.agent_id));if(!agent)return;const id=String(agent.id);const prev=totals.get(id)||{id,name:agentName(agent),units:0,volume:0,gci:0,listings:0,leaseListings:0,saleListings:0};prev.units++;prev.volume+=Math.max(0,Number(t.sale_price??t.purchase_price??0)||0);prev.gci+=Math.max(0,Number(t.gross_commission??0)||0);totals.set(id,prev)});const agentIds=new Set(agents.rows.map(a=>String(a.id)));const addListing=(listing,dateValue,typeValue,agentKeys)=>{const date=String(dateValue||"").slice(0,10),status=String(listing.status||"").toUpperCase(),type=String(typeValue||"").toUpperCase();if(!date||date<startDate||date>endDate||["REJECTED","CANCELLED","DELETED","EXPIRED"].includes(status)||!["LEASE","SALE"].includes(type))return;const ids=agentKeys.filter(v=>v!==null&&v!==undefined&&String(v)!=="").map(String);for(const id of new Set(ids)){if(!agentIds.has(id))continue;const prev=totals.get(id);if(prev){prev.listings++;if(type==="LEASE")prev.leaseListings++;if(type==="SALE")prev.saleListings++}}};listingSubmissions.rows.forEach(listing=>addListing(listing,listing.listing_start_date,listing.listing_type,[listing.agent_id,...(Array.isArray(listing.additional_agent_ids)?listing.additional_agent_ids:[])]));legacyListings.rows.forEach(listing=>addListing(listing,listing.listing_start_date||listing.list_date||listing.listing_date,listing.listing_type||listing.type||listing.transaction_type,[listing.agent_id,listing.listing_agent_id,...(Array.isArray(listing.additional_agent_ids)?listing.additional_agent_ids:[])]));const rows=[...totals.values()];const rankPoints=key=>{const sorted=[...rows].sort((a,b)=>Number(b[key]||0)-Number(a[key]||0));const n=sorted.length;return new Map(sorted.map((row,index)=>[row.id,n<=1?100:100*(n-index-1)/(n-1)]))};const points={units:rankPoints("units"),volume:rankPoints("volume"),gci:rankPoints("gci"),listings:rankPoints("listings")};rows.forEach(row=>row.combinedScore=Math.round(((points.units.get(row.id)||0)+(points.volume.get(row.id)||0)+(points.gci.get(row.id)||0)+(points.listings.get(row.id)||0))/4*100)/100);return rows.filter(row=>config.topMetric==="listings"?row.listings>0:config.topMetric==="combined"?(row.units>0||row.listings>0||row.volume>0||row.gci>0):(row.units>0||row.volume>0||row.gci>0)).sort((a,b)=>(config.topMetric==="units"?b.units-a.units:config.topMetric==="gci"?b.gci-a.gci:config.topMetric==="listings"?b.listings-a.listings:config.topMetric==="combined"?b.combinedScore-a.combinedScore:b.volume-a.volume)||b.volume-a.volume||b.gci-a.gci||a.name.localeCompare(b.name)).slice(0,5)},[transactions.rows,listingSubmissions.rows,legacyListings.rows,agents.rows,config.topAgents,config.topMetric,monthStart,monthEnd]);
