 async function deleteInvoice(row){
  if(!supabase){alert("Database connection is unavailable.");return}
  const reason=window.prompt("Why are you deleting this invoice? This reason will be saved in the audit history.");
  if(reason===null)return;
  if(!reason.trim()){alert("A deletion reason is required.");return}
  const paymentCount=paymentRows.filter(p=>p.expense_id===row.id).length;
  const confirmText="PERMANENTLY DELETE invoice "+(row.invoice_number||"")+(row.vendor?" — "+row.vendor:"")+"?\\n\\nThis removes the invoice, "+paymentCount+" linked payment record(s), and their related journal entries, including expense/HST/AP and payment/liability entries. The chart-of-accounts definitions remain; only entries for this invoice are removed. An audit record will be retained.\\n\\nThis cannot be undone.";
  if(!window.confirm(confirmText))return;
  const{data,error}=await supabase.rpc("dv_accounting_delete_expense_with_payments",{p_expense_id:row.id,p_reason:reason.trim()});
  if(error){alert("Could not delete invoice and linked accounting entries: "+error.message);return}
  let fileWarning="";
  if(row.invoice_storage_path){const{error:fileError}=await supabase.storage.from("dv-vendor-invoices").remove([row.invoice_storage_path]);if(fileError)fileWarning=" The accounting records were deleted, but the stored attachment could not be removed: "+fileError.message}
  if(detailInvoice?.id===row.id)setDetailInvoice(null);
  alert("Invoice deleted. "+(data?.payment_records_deleted||0)+" linked payment(s) and "+(data?.journal_entries_deleted||0)+" related journal entries removed. Audit history was retained."+fileWarning);
  await load();
 }
 function openRecurringEdit(template){
  if(!canManageRecurring){alert("You do not have permission to edit recurring invoice schedules.");return}
  setRecurringEditId(template.id);setRecurringForm({vendor:template.vendor||"",description:template.description||"",category:template.category||"",invoice_total:String(template.invoice_total??""),hst_rate:String(template.hst_rate??"13"),frequency:template.frequency||"MONTHLY",start_date:String(template.start_date||template.next_invoice_date||today()).slice(0,10),next_invoice_date:String(template.next_invoice_date||today()).slice(0,10),due_days:String(template.due_days??"0")});setRecurringShow(true);
 }
 async function deleteRecurring(template){
  if(!canDeleteInvoice){alert("You do not have permission to delete recurring invoice schedules.");return}
  const generated=rows.filter(x=>x.recurring_template_id===template.id).length;
  const msg="Delete the recurring invoice schedule for "+template.vendor+"? This stops future scheduled invoices. "+generated+" invoice(s) already generated from this schedule will remain in Vendor Invoices & Expenses and will not be deleted. This cannot be undone.";
  if(!window.confirm(msg))return;
  const{error}=await supabase.from("dv_accounting_recurring_expenses").delete().eq("id",template.id);
  if(error){alert("Could not delete recurring invoice schedule: "+error.message);return}
  alert("Recurring invoice schedule deleted. Existing generated invoices were kept.");
  await load();
 }
