 <section className="panel"><div className="paneltitle"><h2>CRA payroll remittances</h2><span className="pill">Track payment to CRA</span></div><div className="tablewrap"><table><thead><tr><th>Pay date</th><th>Payroll period</th><th>Due date</th><th>Employee deductions</th><th>Employer CPP/EI</th><th>Total</th><th>Status</th><th></th></tr></thead><tbody>{remittances.rows.map(x=><tr key={x.id}><td>{x.remittance_date||"—"}</td><td>{x.period_start} → {x.period_end}</td><td>{x.due_date||"—"}</td><td>{money(Number(x.income_tax||0)+Number(x.cpp||0)+Number(x.ei||0))}</td><td>{money(Number(x.employer_cpp||0)+Number(x.employer_cpp2||0)+Number(x.employer_ei||0))}</td><td>{money(x.total_remittance)}</td><td><span className="status">{x.status}</span></td><td>{x.status==="OPEN"&&canPayroll("payroll.remit")&&<button className="textbutton" onClick={()=>markRemittancePaid(x.id)}>Mark Paid</button>}</td></tr>)}{!remittances.rows.length&&<tr><td colSpan="10"><Empty icon={ReceiptText} title="No CRA remittances yet" text="Posted payroll creates the remittance record automatically." /></td></tr>}</tbody></table></div><div className="notice"><AlertCircle/> The app tracks the remittance obligation and due date. Payment to CRA should be made through the CRA-approved payment method and then marked paid here; the system does not submit the payment itself.</div></section>
