 const id=record?.id,agentId=entityType==="AGENT"?id:null,employeeId=entityType==="STAFF"?id:null;
 useEffect(()=>{if(!companyId||!supabase)return;let active=true;supabase.from("dv_accounting_settings").select("value").eq("company_id",companyId).eq("key","AGENT_PERSONNEL_DOCUMENT_REQUIREMENTS").maybeSingle().then(({data})=>{if(!active)return;const v=data?.value;if(Array.isArray(v)&&v.length){const normalized=[...v.filter(x=>x&&typeof x.name==="string").map(x=>{const d=DEFAULT_PERSONNEL_DOCUMENT_REQUIREMENTS.find(y=>y.name===x.name);return {name:x.name,expiryRequired:typeof x.expiryRequired==="boolean"?x.expiryRequired:!!d?.expiryRequired,renewalHistoryEnabled:typeof x.renewalHistoryEnabled==="boolean"?x.renewalHistoryEnabled:!!d?.renewalHistoryEnabled,customNameEnabled:!!x.customNameEnabled}})];setDocRequirements(normalized);setDocType(current=>normalized.some(x=>x.name===current)?current:(normalized[0]?.name||"Licence"))}});return()=>{active=false}},[companyId]);
