function PaidCommissionCorrections({commissions=[],transactions=[],agents=[],canManage=false}) {
 const {rows,setRows,load}=useRows("dv_accounting_commission_corrections");
 const [show,setShow]=useState(false),[saving,setSaving]=useState(false);
 const [form,setForm]=useState({commission_id:"",corrected_gross_commission:"",corrected_brokerage_share:"",corrected_agent_share:"",fee_adjustment:"0",reason:"",notes:""});
 const paid=commissions.filter(x=>String(x.status||"").toUpperCase()==="PAID");
 const selected=paid.find(x=>x.id===form.commission_id);
 useEffect(()=>{if(selected)setForm(f=>({...f,corrected_gross_commission:String(selected.gross_commission??0),corrected_brokerage_share:String(selected.brokerage_share??0),corrected_agent_share:String(selected.agent_share??0)}))},[form.commission_id]);
 async function save(e){
  e.preventDefault(); if(!form.commission_id||!form.reason.trim())return;
  setSaving(true);
  const {data,error}=await supabase.rpc("dv_create_paid_commission_correction",{
   p_commission_id:form.commission_id,
   p_corrected_gross_commission:Number(form.corrected_gross_commission||0),
   p_corrected_brokerage_share:Number(form.corrected_brokerage_share||0),
   p_corrected_agent_share:Number(form.corrected_agent_share||0),
   p_fee_adjustment:Number(form.fee_adjustment||0),
   p_reason:form.reason.trim(),p_notes:form.notes.trim()||null
  });
  if(error){alert(error.message);setSaving(false);return}
  setRows(x=>[data,...x]);setShow(false);setForm({commission_id:"",corrected_gross_commission:"",corrected_brokerage_share:"",corrected_agent_share:"",fee_adjustment:"0",reason:"",notes:""});setSaving(false);await load();
 }
 const moneyDelta=n=>money(n);
 return <section className="panel tablewrap">
  <div className="paneltitle"><div><h2>Paid Commission Corrections</h2><p className="panelhint">Corrections are recorded in an audit ledger. The original paid commission is never overwritten and no payment is automatically issued or recovered.</p></div>{canManage&&<button className="primary" onClick={()=>setShow(true)}><Plus size={16}/> New Correction</button>}</div>
  <table><thead><tr><th>Correction #</th><th>Trade #</th><th>Agent</th><th>Original Agent Share</th><th>Corrected Agent Share</th><th>Delta</th><th>Reason</th><th>Status</th><th>Date</th></tr></thead><tbody>
   {rows.map(x=>{const tx=transactions.find(t=>t.id===x.transaction_id);const ag=agents.find(a=>a.id===x.agent_id);return <tr key={x.id}><td>{x.correction_number??"—"}</td><td>{tx?.transaction_number||"—"}</td><td>{ag?.name||[ag?.first_name,ag?.last_name].filter(Boolean).join(" ")||"—"}</td><td>{money(x.original_agent_share)}</td><td>{money(x.corrected_agent_share)}</td><td>{moneyDelta(x.agent_share_delta)}</td><td>{x.reason}</td><td><span className="status">{x.status}</span></td><td>{x.created_at?new Date(x.created_at).toLocaleDateString("en-CA"):"—"}</td></tr>})}
   {!rows.length&&<tr><td colSpan="9"><div className="empty small"><ReceiptText/><h3>No corrections recorded</h3><p>Corrections to paid commissions will be listed here for audit and follow-up.</p></div></td></tr>}
  </tbody></table>
  {show&&<Modal title="Correct Paid Commission" onClose={()=>setShow(false)}><form onSubmit={save}>
   <div className="formgrid">
    <label>Paid commission<select required value={form.commission_id} onChange={e=>setForm({...form,commission_id:e.target.value})}><option value="">Select paid commission</option>{paid.map(x=>{const tx=transactions.find(t=>t.id===x.transaction_id);const ag=agents.find(a=>a.id===x.agent_id);return <option key={x.id} value={x.id}>{tx?.transaction_number||"No trade #"} · {ag?.name||[ag?.first_name,ag?.last_name].filter(Boolean).join(" ")||"Agent"} · {money(x.agent_share)}</option>})}</select></label>
    <label>Corrected gross commission<MoneyInput min="0" step=".01" required value={form.corrected_gross_commission} onChange={e=>setForm({...form,corrected_gross_commission:e.target.value})}/></label>
    <label>Corrected brokerage share<MoneyInput min="0" step=".01" required value={form.corrected_brokerage_share} onChange={e=>setForm({...form,corrected_brokerage_share:e.target.value})}/></label>
    <label>Corrected agent share<MoneyInput min="0" step=".01" required value={form.corrected_agent_share} onChange={e=>setForm({...form,corrected_agent_share:e.target.value})}/></label>
    <label>Fee adjustment (+/-)<MoneyInput step=".01" value={form.fee_adjustment} onChange={e=>setForm({...form,fee_adjustment:e.target.value})}/></label>
    <label>Reason<input required value={form.reason} onChange={e=>setForm({...form,reason:e.target.value})} placeholder="Explain why the correction is required"/></label>
    <label style={{gridColumn:"1 / -1"}}>Notes<textarea rows="3" value={form.notes} onChange={e=>setForm({...form,notes:e.target.value})}/></label>
   </div>
   {selected&&<div className="notice"><AlertCircle/> Original paid amount: {money(selected.agent_share)}. Proposed agent-share difference: {money(Number(form.corrected_agent_share||0)-Number(selected.agent_share||0)+Number(form.fee_adjustment||0))}. This creates an audit record only; settle any amount separately through accounting.</div>}
   <div className="modalactions"><button type="button" className="secondary" onClick={()=>setShow(false)}>Cancel</button><button className="primary" disabled={saving||!paid.length}><Save size={16}/>{saving?"Saving...":"Save Correction"}</button></div>
  </form></Modal>}
 </section>
}


