 const toDate=previous+(issued?Number(issued.net_amount||total):total);const toDateGross=previousGross+Number(commission?.gross_commission||transaction?.gross_commission||0);const toDateHst=previousHst+Number(issued?.agent_hst_amount??hst);
 const issuedFeeCorrection=issued&&(issued.general_expense!==undefined||issued.desk_fees!==undefined)?0:charges.filter(ch=>ch.agent_id===agent?.id&&["DESK_FEE","GENERAL_EXPENSE","GENERAL_EXP","OTHER_FEE"].includes(String(ch.charge_type||"").toUpperCase())&&true&&((issued?.id&&ch.applied_to_cheque_id===issued.id)||(["OPEN","PARTIAL"].includes(String(ch.status||"").toUpperCase())&&!ch.applied_to_cheque_id))).reduce((sum,ch)=>sum+Math.max(0,Number(ch.amount||0)-Number(ch.paid_amount||0))+(ch.hst_applicable?Number(ch.hst_amount||0):0),0);
