 async function issue(){
  if(!supabase)return;
  if(!arReady){setError(sellerSettlement?"Payment blocked — finish paying the seller/landlord and post the commission transfer from Real Estate Trust to Commission Trust first.":"Payment blocked — record the full commission AR receipt in the Commission Trust account and link it to this transaction before issuing.");return}
  if(method==="EFT"&&!reference.trim()){setError("Enter the EFT payment reference before issuing.");return}
  if(method==="CHEQUE"&&!reference.trim()){setError("Enter the cheque number before issuing.");return}
  setBusy(true);setError("");
  const{data,error}=await supabase.rpc("dv_accounting_issue_commission_cheque",{p_commission_id:commission.id,p_cheque_number:reference.trim(),p_cheque_date:payDate,p_deduct_desk_fees:deductDeskFees});
  if(error){setError(error.message);setBusy(false);return}
  const{error:updateError}=await supabase.from("dv_accounting_commission_cheques").update({payment_method:method,payment_reference:reference.trim()}).eq("id",data.cheque_id);
  if(updateError){setError("Payment was issued, but the payment method could not be saved. Run migration 0055 and contact an administrator before continuing. "+updateError.message);setBusy(false);return}
  const{data:canonicalCheque,error:chequeReadError}=await supabase.from("dv_accounting_commission_cheques").select("*").eq("id",data.cheque_id).single();
  if(chequeReadError||!canonicalCheque){setError("Payment was issued, but the saved cheque could not be reloaded. Refresh Commission Payroll before printing; do not issue a second payment.");setBusy(false);return}
  setIssued(canonicalCheque);setMethod(canonicalCheque.payment_method||method);setReference(canonicalCheque.payment_reference||canonicalCheque.cheque_number||reference.trim());setPayDate(canonicalCheque.cheque_date||payDate);setBusy(false);await onIssued?.();
 }
 async function saveIssuedDetails(){
  if(!issued?.id||!reference.trim()||!payDate){setError("Enter a payment reference and payment date.");return}
  setBusy(true);setError("");
  const update={payment_method:method,payment_reference:reference.trim(),cheque_date:payDate,cheque_number:method==="CHEQUE"?reference.trim():(issued.cheque_number||null)};
  const {data,error:saveError}=await supabase.from("dv_accounting_commission_cheques").update(update).eq("id",issued.id).select("*").single();
  if(saveError||!data){setError(saveError?.message||"Could not save payment details.");setBusy(false);return}
  setIssued(data);setMethod(data.payment_method||method);setReference(data.payment_reference||data.cheque_number||reference.trim());setPayDate(String(data.cheque_date||payDate).slice(0,10));setEditingIssued(false);setBusy(false);await onIssued?.();
 }
