 const catalog=useRows("dv_accounting_permission_catalog"),roleRules=useRows("dv_accounting_role_permission_rules"),userRules=useRows("dv_accounting_user_permission_overrides"),settings=useRows("dv_accounting_settings");
 const[mode,setMode]=useState("role"),[selectedRole,setSelectedRole]=useState("STAFF"),[selectedUser,setSelectedUser]=useState(""),[busyCode,setBusyCode]=useState(""),[dashboardVisible,setDashboardVisible]=useState(["birthdays","anniversaries","licences","balances","closings","topAgents"]),[dashboardBusy,setDashboardBusy]=useState(false),[roleDraft,setRoleDraft]=useState({}),[userDraft,setUserDraft]=useState({}),[permissionSaving,setPermissionSaving]=useState(false),[permissionMessage,setPermissionMessage]=useState("");
 const role=String(user?.app_metadata?.role||user?.user_metadata?.role||profiles?.find(p=>p.user_id===user?.id)?.role||"STAFF").toUpperCase(),canManage=role==="SUPERADMIN"||!!permissions["settings.roles.manage"]?.allowed;
 useEffect(()=>{if(!selectedUser&&profiles?.length){const target=profiles.find(p=>p.user_id!==user?.id);if(target)setSelectedUser(target.user_id)}},[profiles,selectedUser,user?.id]);
