 async function saveDashboardVisibility(){if(!canManage||!selectedUser||!supabase)return;const setting=settings.rows.find(x=>x.key==="DASHBOARD_WIDGETS");const company=setting?.company_id||settings.rows.find(x=>x.company_id)?.company_id;if(!company){alert("Set up the company and save dashboard settings before configuring user dashboards.");return}setDashboardBusy(true);const value={...(setting?.value||{}),userVisibility:{...(setting?.value?.userVisibility||{}),[selectedUser]:dashboardVisible}};const{data,error}=await supabase.from("dv_accounting_settings").upsert({company_id:company,key:"DASHBOARD_WIDGETS",value},{onConflict:"company_id,key"}).select().single();if(error)alert("Could not save dashboard visibility: "+error.message);else settings.setRows(rows=>rows.some(x=>x.key==="DASHBOARD_WIDGETS"&&x.company_id===company)?rows.map(x=>x.key==="DASHBOARD_WIDGETS"&&x.company_id===company?data:x):[...rows,data]);setDashboardBusy(false)}
 const roleRule=code=>roleDraft[code]||roleRules.rows.find(x=>x.role===selectedRole&&x.permission_code===code),userRule=code=>Object.prototype.hasOwnProperty.call(userDraft,code)?userDraft[code]:userRules.rows.find(x=>x.user_id===selectedUser&&x.permission_code===code);
 useEffect(()=>{setRoleDraft({});setPermissionMessage("")},[selectedRole]);
