 function setRoleRule(item,allowed,scope){if(!canManage||selectedRole==="SUPERADMIN")return;const current=roleRules.rows.find(x=>x.role===selectedRole&&x.permission_code===item.code);setRoleDraft(old=>({...old,[item.code]:{role:selectedRole,permission_code:item.code,allowed,access_scope:scope||current?.access_scope||"ALL"}}));setPermissionMessage("")}
 async function saveRoleRules(){if(!supabase||!canManage||selectedRole==="SUPERADMIN")return;setPermissionSaving(true);setPermissionMessage("");try{for(const [code,rule] of Object.entries(roleDraft)){const{data,error}=await supabase.rpc("dv_accounting_set_role_permission",{p_role:selectedRole,p_permission_code:code,p_allowed:!!rule.allowed,p_scope:rule.access_scope||"ALL"});if(error)throw error;roleRules.setRows(rows=>rows.some(x=>x.role===selectedRole&&x.permission_code===code)?rows.map(x=>x.role===selectedRole&&x.permission_code===code?data:x):[...rows,data])}setRoleDraft({});setPermissionMessage("Role permissions saved.")}catch(e){setPermissionMessage("Could not save all role permissions: "+(e?.message||String(e)))}finally{setPermissionSaving(false)}}
