 const[settingsSection,setSettingsSection]=useState("COMPANY"),[show,setShow]=useState(false),[saving,setSaving]=useState(false),[form,setForm]=useState({name:"Dream Valley Realty Inc., Brokerage",legal_name:"Dream Valley Realty Inc.",hst_number:""}),[bankShow,setBankShow]=useState(false),[bank,setBank]=useState({name:"",account_type:"OPERATING",institution:"",account_number_last4:"",opening_balance:"0"}),[payrollForm,setPayrollForm]=useState({frequency:"MONTHLY",payroll_account_number:""});
 const chequeDefaults={paperWidth:8.5,paperHeight:11,chequeHeight:3.67,chequeTop:0,leftOffset:0,topOffset:0,fontSize:10,positions:{date:{x:6.4,y:0.45},payee:{x:0.7,y:1.15},amountNumeric:{x:6.5,y:1.15},amountWords:{x:0.7,y:1.65},memo:{x:0.7,y:2.6},chequeNumber:{x:7.1,y:0.25}}};
 const [chequeBankId,setChequeBankId]=useState(""),[chequeConfig,setChequeConfig]=useState(chequeDefaults),[chequeSaving,setChequeSaving]=useState(false);
 const [chequeDisplayOptionsShow,setChequeDisplayOptionsShow]=useState(false);
